/**
 * Pre-compiled standalone single-file HTML application bundle.
 * Generated automatically. Allows 100% client-side Blob download without cross-origin HTTP auth block.
 */
export function downloadStandaloneHtmlFile(onSuccess?: (msg: string) => void) {
  try {
    const blob = new Blob([STANDALONE_HTML], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'DayNight_昼夜簿_单文件本地版.html';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    if (onSuccess) {
      onSuccess('已开始下载单文件离线版！双击即可在本地电脑直接运行。');
    }
  } catch (err) {
    console.error('Download HTML failed:', err);
  }
}

